(function() {
	//#region src/Modules/CrestApps.OrchardCore.Commerce/Assets/js/commerce-admin-list.js
	(function() {
		"use strict";
		function submitFilters(select) {
			var form = select.form;
			if (!form) return;
			var submit = form.querySelector("[name=\"submit.Filter\"]");
			if (submit) submit.click();
			else form.submit();
		}
		document.addEventListener("DOMContentLoaded", function() {
			var filters = document.querySelectorAll("[data-commerce-list-filter]");
			for (var i = 0; i < filters.length; i++) filters[i].addEventListener("change", function(event) {
				submitFilters(event.currentTarget);
			});
		});
	})();
	//#endregion
})();
